import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"晓来天气浓淡","description":"","frontmatter":{"title":"晓来天气浓淡","date":"2026-11-20T00:00:00.000Z","seq":92,"categories":["美文","全宋词"],"collection":"《全宋词 · 柳永》","tags":["全宋词","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"全宋词","prev":{"text":"恋帝里","link":"/blogs/全宋词·柳永/恋帝里.html"},"next":{"text":"小楼深巷狂游遍","link":"/blogs/全宋词·柳永/小楼深巷狂游遍.html"}},"headers":[],"relativePath":"blogs/全宋词·柳永/晓来天气浓淡.md","filePath":"blogs/全宋词·柳永/晓来天气浓淡.md"}'),o={name:"blogs/全宋词·柳永/晓来天气浓淡.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="晓来天气浓淡" tabindex="-1">晓来天气浓淡 <a class="header-anchor" href="#晓来天气浓淡" aria-label="Permalink to &quot;晓来天气浓淡&quot;">​</a></h1><p class="poem-meta">宋 · 柳永　·　抛球乐</p><div class="poem"><p class="poem-stanza">晓来天气浓淡，微雨轻洒。</p><p class="poem-stanza">近清明，风絮巷陌，烟草池塘，尽堪图画。</p><p class="poem-stanza">艳杏暖、妆脸匀开，弱柳困、宫腰低亚。</p><p class="poem-stanza">是处丽质盈盈，巧笑嬉嬉，手簇秋千架。</p><p class="poem-stanza">戏彩球罗绶，金鸡芥羽，少年驰骋，芳郊绿野。</p><p class="poem-stanza">占断五陵游，奏脆管、繁弦声和雅。</p><p class="poem-stanza">向名园深处，争泥画轮，竞羁宝马。</p><p class="poem-stanza">取次罗列杯盘，就芳树、绿阴红影下。</p><p class="poem-stanza">舞婆娑，歌宛转，仿佛莺娇燕姹。</p><p class="poem-stanza">寸珠片玉，争似此、浓欢无价。</p><p class="poem-stanza">任他美酒，十千一斗，饮竭仍解金貂贳。</p><p class="poem-stanza">恣幕天席地，陶陶尽醉太平，且乐唐虞景化。</p><p class="poem-stanza">须信艳阳天，看未足、已觉莺花谢。</p><p class="poem-stanza">对绿蚁翠蛾，怎忍轻舍。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
